export const AUTHENTIC_GIFTS = Object.freeze(catalog.map(gift => Object.freeze({
  ...gift, requirements: Object.freeze(gift.requirements),
  ...(gift.tuning ? {tuning: Object.freeze(gift.tuning)} : {}),
})));
const byId = new Map(AUTHENTIC_GIFTS.map(gift => [gift.id, gift]));

export function eligibleGifts(profile, giftIds = [], {allowOwned=false} = {}) {
  const owned = new Set(giftIds);
  const secondary = resolveJobSkill(profile, 3);
  return AUTHENTIC_GIFTS.filter(gift => {
    if (!allowOwned && owned.has(gift.id)) return false;
    if (gift.originalId === 1001 && owned.has("original-1003")) return false;
    if (gift.originalId === 1003 && owned.has("original-1001")) return false;
    // Opposed elixir channels are mutually exclusive by local design, not server evidence.
    if (gift.originalId === 10001 && owned.has("original-10002")) return false;
    if (gift.originalId === 10002 && owned.has("original-10001")) return false;
    if (gift.originalId === 14502 && !profile.petActive) return false;
    const req = gift.requirements;
    if (req.weapon && req.weapon !== profile.weapon) return false;
    if (req.secondary && (req.secondary !== profile.secondary || WEAPONS[profile.weapon]?.twoHanded)) return false;
    if (req.job && !(profile.job === req.job || secondary?.job === req.job && secondary.skill === req.skill)) return false;
    return true;
  });
}

export function giftBonus(giftIds, effect) {
  return giftIds.reduce((sum, id) => {
    const gift = byId.get(id);
    return sum + (gift?.effect === effect ? gift.amount : 0);
  }, 0);
}
